begin;
select no_plan();
select ok(private.partner_schedule_valid('[]','[]','[]'),'empty draft valid');
select ok(not private.partner_schedule_valid(jsonb_build_array(jsonb_build_object('weekday',0,'startMinute',0,'endMinute',60,'ignored',repeat('x',262144))),'[]','[]'),'aggregate bytes bounded before validation');
select ok(private.partner_schedule_valid((select jsonb_agg(jsonb_build_object('weekday',0,'startMinute',x*2,'endMinute',x*2+1)) from generate_series(0,127) x),'[]','[]'),'128 openings accepted');
select ok(private.partner_schedule_valid('[]','[]',(select jsonb_agg(jsonb_build_object('date','2026-01-01','startMinute',x*2,'endMinute',x*2+1)) from generate_series(0,511) x)),'512 blocks accepted');
select ok(private.partner_schedule_valid('[{"weekday":0,"startMinute":0,"endMinute":60,"ignored":"ok"}]','[]','[]'),'unknown fields match domain behavior');
select ok(not private.partner_schedule_valid((select jsonb_agg(jsonb_build_object('weekday',0,'startMinute',x*2,'endMinute',x*2+1)) from generate_series(0,128) x),'[]','[]'),'opening interval count bounded');
select ok(not private.partner_schedule_valid('[{"weekday":0,"startMinute":0,"endMinute":1440}]',(select jsonb_agg(jsonb_build_object('weekday',0,'startMinute',x*2,'endMinute',x*2+1)) from generate_series(0,128) x),'[]'),'break interval count bounded');
select ok(not private.partner_schedule_valid('[]','[]',(select jsonb_agg(jsonb_build_object('date','2026-01-01','startMinute',x*2,'endMinute',x*2+1)) from generate_series(0,512) x)),'block interval count bounded');
select ok(not private.partner_schedule_valid(null,'[]','[]'),'SQL null rejected');
select ok(not private.partner_schedule_valid('null','[]','[]'),'JSON null rejected');
select ok(not private.partner_schedule_valid('{}','[]','[]'),'object aggregate rejected');
select ok(not private.partner_schedule_valid('[null]','[]','[]'),'null interval rejected');
select ok(not private.partner_schedule_valid('[{"weekday":0,"startMinute":0}]','[]','[]'),'missing end rejected');
select ok(not private.partner_schedule_valid('[{"weekday":0,"startMinute":"0","endMinute":60}]','[]','[]'),'string number rejected');
select ok(not private.partner_schedule_valid('[{"weekday":0,"startMinute":0.5,"endMinute":60}]','[]','[]'),'fraction rejected');
select ok(not private.partner_schedule_valid('[{"weekday":-1,"startMinute":0,"endMinute":60}]','[]','[]'),'negative weekday rejected');
select ok(not private.partner_schedule_valid('[{"weekday":7,"startMinute":0,"endMinute":60}]','[]','[]'),'weekday seven rejected');
select ok(not private.partner_schedule_valid('[{"weekday":1.5,"startMinute":0,"endMinute":60}]','[]','[]'),'fraction weekday rejected');
select ok(not private.partner_schedule_valid('[{"weekday":0,"startMinute":0,"endMinute":0}]','[]','[]'),'zero length rejected');
select ok(not private.partner_schedule_valid('[{"weekday":0,"startMinute":-1,"endMinute":60}]','[]','[]'),'negative minute rejected');
select ok(not private.partner_schedule_valid('[{"weekday":0,"startMinute":0,"endMinute":1441}]','[]','[]'),'over day rejected');
select ok(not private.partner_schedule_valid('[{"weekday":0,"startMinute":1300,"endMinute":60}]','[]','[]'),'overnight rejected');
select ok(not private.partner_schedule_valid('[{"weekday":0,"startMinute":0,"endMinute":60},{"weekday":0,"startMinute":30,"endMinute":90}]','[]','[]'),'hours overlap rejected');
select ok(private.partner_schedule_valid('[{"weekday":0,"startMinute":0,"endMinute":60},{"weekday":0,"startMinute":60,"endMinute":90}]','[]','[]'),'adjacent openings valid');
select ok(private.partner_schedule_valid('[{"weekday":0,"startMinute":0,"endMinute":60},{"weekday":1,"startMinute":0,"endMinute":60}]','[]','[]'),'different weekdays valid');
select ok(not private.partner_schedule_valid('[{"weekday":0,"startMinute":0,"endMinute":180}]','[{"weekday":0,"startMinute":30,"endMinute":90},{"weekday":0,"startMinute":60,"endMinute":120}]','[]'),'break overlap rejected');
select ok(not private.partner_schedule_valid('[{"weekday":0,"startMinute":0,"endMinute":60}]','[{"weekday":0,"startMinute":30,"endMinute":90}]','[]'),'break outside rejected');
select ok(not private.partner_schedule_valid('[{"weekday":0,"startMinute":0,"endMinute":60},{"weekday":0,"startMinute":60,"endMinute":120}]','[{"weekday":0,"startMinute":30,"endMinute":90}]','[]'),'break cannot span adjacent openings');
select ok(private.partner_schedule_valid('[{"weekday":0,"startMinute":0,"endMinute":180}]','[{"weekday":0,"startMinute":30,"endMinute":60},{"weekday":0,"startMinute":60,"endMinute":90}]','[]'),'adjacent contained breaks valid');
select ok(not private.partner_schedule_valid('[]','[]','[{"date":"2026-02-29","startMinute":0,"endMinute":60}]'),'nonleap date rejected');
select ok(not private.partner_schedule_valid('[]','[]','[{"date":"1900-02-29","startMinute":0,"endMinute":60}]'),'century nonleap rejected');
select ok(private.partner_schedule_valid('[]','[]','[{"date":"2000-02-29","startMinute":0,"endMinute":60}]'),'400 year leap valid');
select ok(private.partner_schedule_valid('[]','[]','[{"date":"0000-02-29","startMinute":0,"endMinute":60}]'),'Gregorian year zero matches domain');
select ok(not private.partner_schedule_valid('[]','[]','[{"date":"2026-04-31","startMinute":0,"endMinute":60}]'),'invalid month day rejected');
select ok(not private.partner_schedule_valid('[]','[]','[{"date":"2026-1-01","startMinute":0,"endMinute":60}]'),'noncanonical date rejected');
select ok(not private.partner_schedule_valid('[]','[]','[{"date":null,"startMinute":0,"endMinute":60}]'),'null date rejected');
select ok(not private.partner_schedule_valid('[]','[]','[{"date":"2026-01-01","startMinute":0,"endMinute":60},{"date":"2026-01-01","startMinute":30,"endMinute":90}]'),'blocks overlap rejected');
select ok(private.partner_schedule_valid('[]','[]','[{"date":"2026-01-01","startMinute":0,"endMinute":60},{"date":"2026-01-01","startMinute":60,"endMinute":90},{"date":"2026-01-02","startMinute":0,"endMinute":60}]'),'adjacent and different date blocks valid');
insert into auth.users(id,email) values ('d0000000-0000-0000-0000-000000000001','schedule@example.test');
insert into public.merchants(id) values ('d0000000-0000-0000-0000-000000000002');
insert into public.merchant_memberships(merchant_id,user_id) values ('d0000000-0000-0000-0000-000000000002','d0000000-0000-0000-0000-000000000001');
set local role authenticated;
set local request.jwt.claim.sub='d0000000-0000-0000-0000-000000000001';
select results_eq($$insert into public.merchant_schedules(merchant_id) values ('d0000000-0000-0000-0000-000000000002') returning hours::text$$,array['[]'],'owner creates empty aggregate returning');
select lives_ok($$update public.merchant_schedules set hours='[{"weekday":0,"startMinute":0,"endMinute":120},{"weekday":0,"startMinute":180,"endMinute":240}]',breaks='[{"weekday":0,"startMinute":30,"endMinute":60}]',blocks='[{"date":"2028-02-29","startMinute":0,"endMinute":1440}]'$$,'owner writes valid multi interval aggregate');
select throws_ok($$update public.merchant_schedules set breaks='[{"weekday":0,"startMinute":100,"endMinute":200}]'$$,'23514',null,'stored CHECK rejects invalid owner update');
select is((select breaks::text from public.merchant_schedules),'[{"weekday": 0, "endMinute": 60, "startMinute": 30}]','failed update preserves stored aggregate');
select throws_ok($$update public.merchant_schedules set merchant_id=gen_random_uuid()$$,'42501',null,'schedule identifier cannot transfer');
select is((select count(*) from public.merchant_audit_events where entity_table='merchant_schedules' and action='UPDATE'),1::bigint,'invalid schedule update does not audit');
select * from finish();
rollback;
